SELECT city, rating_bucket, chiang_mai_rating, de_rating FROM (SELECT city, CASE WHEN rating >= 3.9 THEN 'high' WHEN rating >= 1.5 THEN 'mid' ELSE 'low' END rating_bucket, SUM(CASE WHEN city = 'Chiang Mai' THEN rating ELSE 0 END) chiang_mai_rating, SUM(CASE WHEN country = 'DE' THEN rating ELSE 0 END) de_rating FROM suppliers WHERE rating BETWEEN 1.8 AND 4.1 GROUP BY city, CASE WHEN rating >= 3.9 THEN 'high' WHEN rating >= 1.5 THEN 'mid' ELSE 'low' END) s WHERE chiang_mai_rating < 36 ORDER BY city, rating_bucket LIMIT 50;
